{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Codeine, the closest analogue sharing the methoxy-substituted aromatic, allylic alcohol, ether bridge, and N-methyl tertiary amine, has absolute oral bioavailability of 42–71% in healthy volunteers, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Codeine sulfate in healthy subjects showed oral bioavailability of 80.5%, confirming that the codeine-like scaffold is well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Ethylmorphine, an ethoxy homologue of codeine, had systemic availability of 0.74 (range 0.54–0.92), supporting high oral bioavailability for the closely related query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Diacetylmorphine, a more derivatized morphinan, still showed oral bioavailability of 45.6% at low dose, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Morphine, a related morphinan lacking the methoxy group, had absolute F of 0.196 in one human study, just below the threshold; this is the only near-threshold low value and is outweighed by higher-scoring codeine evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and most transferable analogues (codeine, ethylmorphine, diacetylmorphine) consistently show oral bioavailability well above 20%; morphine is mostly above 20% with one borderline value. The query's tetracyclic alkaloid scaffold shares key absorption-permissive features with codeine, so high is better supported.",
  "evidence_gaps": [
    "No direct oral bioavailability record for the exact query molecule in the evidence set.",
    "Closest evidence (codeine) has only moderate Morgan similarity to the query.",
    "No specific metabolism/transporter data for the query to rule out first-pass loss."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

